from fastapi import FastAPI
from fastapi.responses import JSONResponse

app = FastAPI()

STORE: dict[int, str] = {}
STORE[{{item_id}}] = "on its way"

# The code the tower sends back for each outcome
# >>> EDIT START
FOUND = 500
CREATED = 500
MISSING = 500
# <<< EDIT END


def signal(code: int, **body: object) -> JSONResponse:
    return JSONResponse(status_code=code, content=body)


@app.get("/{{thing}}s/{item_id}")
async def track(item_id: int) -> JSONResponse:
    if item_id not in STORE:
        return signal(MISSING, error="no such {{thing}}")
    return signal(FOUND, id=item_id, status=STORE[item_id])


@app.post("/{{thing}}s")
async def send() -> JSONResponse:
    return signal(CREATED, id=99, status="accepted")
